/* Generated by Trae Work — 动物集市交接文档图表 */
(function () {
  if (typeof echarts === 'undefined') return;
  var css = getComputedStyle(document.documentElement);
  var P = {
    bg2: css.getPropertyValue('--bg2').trim() || '#151b24',
    bg3: css.getPropertyValue('--bg3').trim() || '#1c2431',
    ink: css.getPropertyValue('--ink').trim() || '#d7dee8',
    muted: css.getPropertyValue('--muted').trim() || '#8a94a5',
    rule: css.getPropertyValue('--rule').trim() || '#29323f',
    accent: css.getPropertyValue('--accent').trim() || '#5ec8d8',
    accent2: css.getPropertyValue('--accent2').trim() || '#e8a84c',
    good: css.getPropertyValue('--good').trim() || '#67c98a',
    bad: css.getPropertyValue('--bad').trim() || '#e0687c'
  };
  var mono = "'JetBrains Mono', Consolas, monospace";
  function base() {
    return {
      backgroundColor: 'transparent',
      animation: false,
      textStyle: { color: P.ink, fontFamily: mono, fontSize: 12 },
      tooltip: {
        appendToBody: true, backgroundColor: P.bg3, borderColor: P.rule,
        textStyle: { color: P.ink, fontFamily: mono, fontSize: 12 }
      }
    };
  }

  /* ---- 图 1：阶段完成度（加权条形） ---- */
  var elStage = document.getElementById('chart-stage');
  if (elStage) {
    var stages = [
      { n: 'P6 迭代扩展', v: 0, w: '—' },
      { n: 'P5 场景/构建', v: 5, w: '20%' },
      { n: 'P4 特效系统', v: 100, w: '5%' },
      { n: 'P3 view 组件', v: 90, w: '30%' },
      { n: 'P2 数值回归', v: 100, w: '15%' },
      { n: 'P1 core 移植', v: 100, w: '25%' },
      { n: 'P0 工程脚手架', v: 60, w: '5%' }
    ];
    var c1 = echarts.init(elStage);
    c1.setOption(Object.assign(base(), {
      grid: { left: 8, right: 60, top: 8, bottom: 8, containLabel: true },
      xAxis: {
        type: 'value', max: 100, splitLine: { lineStyle: { color: P.rule } },
        axisLabel: { color: P.muted, formatter: '{value}%' }
      },
      yAxis: {
        type: 'category', data: stages.map(function (s) { return s.n; }),
        axisLine: { lineStyle: { color: P.rule } }, axisTick: { show: false },
        axisLabel: { color: P.ink }
      },
      series: [{
        type: 'bar', data: stages.map(function (s) {
          return { value: s.v, itemStyle: { color: s.v >= 100 ? P.accent : (s.v > 0 ? P.accent2 : P.rule), borderRadius: [0, 4, 4, 0] } };
        }),
        barWidth: 16,
        label: {
          show: true, position: 'right', color: P.muted, fontFamily: mono, fontSize: 11,
          formatter: function (p) { return p.value + '%  ·  权重 ' + stages[p.dataIndex].w; }
        }
      }]
    }));
    window.addEventListener('resize', function () { c1.resize(); });
  }

  /* ---- 图 2：难度曲线（一审/恢复后胜率折线 + 挤爆率柱） ---- */
  var elCurve = document.getElementById('chart-curve');
  if (elCurve) {
    var lv = ['L1','L2','L3','L4','L5','L6','L7','L8','L9','L10','L11','L12'];
    var first = [100, 100, 99.5, 98.8, 97.0, 87.3, 83.8, 75.0, 65.0, 58.5, 53.3, 55.3];
    var revived = [100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100];
    var crowd = [0, 0, 0.5, 1.3, 3.0, 12.8, 16.0, 25.0, 33.0, 40.0, 45.3, 43.5];
    var c2 = echarts.init(elCurve);
    c2.setOption(Object.assign(base(), {
      legend: { data: ['一审胜率', '广告恢复后', '围栏挤爆率'], textStyle: { color: P.muted, fontFamily: mono }, top: 0 },
      grid: { left: 8, right: 8, top: 36, bottom: 8, containLabel: true },
      xAxis: {
        type: 'category', data: lv, boundaryGap: true,
        axisLine: { lineStyle: { color: P.rule } }, axisLabel: { color: P.muted },
        axisTick: { show: false }
      },
      yAxis: {
        type: 'value', max: 100, min: 0,
        splitLine: { lineStyle: { color: P.rule } },
        axisLabel: { color: P.muted, formatter: '{value}%' }
      },
      series: [
        {
          name: '围栏挤爆率', type: 'bar', data: crowd, barWidth: 14,
          itemStyle: { color: 'rgba(224,104,124,.35)', borderRadius: [3, 3, 0, 0] }
        },
        {
          name: '一审胜率', type: 'line', data: first, smooth: false,
          symbol: 'circle', symbolSize: 7, lineStyle: { width: 2.5, color: P.accent2 },
          itemStyle: { color: P.accent2 },
          markLine: {
            silent: true, symbol: 'none',
            lineStyle: { color: P.good, type: 'dashed' },
            label: { color: P.good, fontFamily: mono, fontSize: 11, formatter: '教学线 95%' },
            data: [{ yAxis: 95 }]
          }
        },
        {
          name: '广告恢复后', type: 'line', data: revived,
          symbol: 'circle', symbolSize: 6, lineStyle: { width: 2, color: P.good },
          itemStyle: { color: P.good }
        }
      ]
    }));
    window.addEventListener('resize', function () { c2.resize(); });
  }
})();
